   906  otError Leader::AddHasRoute(PrefixTlv &aPrefix, HasRouteTlv &aHasRoute)
   907  {
   908      otError      error        = OT_ERROR_NONE;
   909      PrefixTlv *  dstPrefix    = NULL;
   910      HasRouteTlv *dstHasRoute  = NULL;
   911      uint16_t     appendLength = 0;
   912
   913      VerifyOrExit(aHasRoute.GetNumEntries() > 0, error = OT_ERROR_PARSE);
   914
   915      if ((dstPrefix = FindPrefix(aPrefix.GetPrefix(), aPrefix.GetPrefixLength())) != NULL)
   916      {
   917          dstHasRoute = FindHasRoute(*dstPrefix, aHasRoute.IsStable());
   918      }
   919
   920      if (dstPrefix == NULL)
   921      {
   922          appendLength += sizeof(PrefixTlv) + BitVectorBytes(aPrefix.GetPrefixLength());
   923      }
   924
   925      if (dstHasRoute == NULL)
   926      {
   927          appendLength += sizeof(HasRouteTlv);
   928      }
   929
   930      appendLength += sizeof(HasRouteEntry);
   931
   932      VerifyOrExit(mLength + appendLength <= sizeof(mTlvs), error = OT_ERROR_NO_BUFS);
   933
   934      if (dstPrefix == NULL)
   935      {
  1088      ContextTlv *     dstContext      = NULL;
  1089      BorderRouterTlv *dstBorderRouter = NULL;
  1090      int              contextId       = -1;
  1091      uint16_t         appendLength    = 0;
  1092
  1093      VerifyOrExit(aBorderRouter.GetNumEntries() > 0, error = OT_ERROR_PARSE);
  1094
  1095      if ((dstPrefix = FindPrefix(aPrefix.GetPrefix(), aPrefix.GetPrefixLength())) != NULL)
  1096      {
  1097          dstContext      = FindContext(*dstPrefix);
  1098          dstBorderRouter = FindBorderRouter(*dstPrefix, aBorderRouter.IsStable());
  1099      }
  1100
  1101      if (dstPrefix == NULL)
  1102      {
  1103          appendLength += sizeof(PrefixTlv) + BitVectorBytes(aPrefix.GetPrefixLength());
  1104      }
  1105
  1106      if (dstContext == NULL)
  1107      {
  1108          appendLength += sizeof(ContextTlv);
  1109      }
  1110
  1111      if (dstBorderRouter == NULL)
  1112      {
  1113          appendLength += sizeof(BorderRouterTlv);
  1114      }
  1115
  1116      appendLength += sizeof(BorderRouterEntry);
  1117
  1118      VerifyOrExit(mLength + appendLength <= sizeof(mTlvs), error = OT_ERROR_NO_BUFS);
  1119
  1120      if (dstContext == NULL)
  1121      {
  1122          contextId = AllocateContext();
  1123          VerifyOrExit(contextId >= 0, error = OT_ERROR_NO_BUFS);
  1124      }
  1125
  1126      if (dstPrefix == NULL)
  1127      {
  1128          dstPrefix = reinterpret_cast<PrefixTlv *>(mTlvs + mLength);
  1129          Insert(reinterpret_cast<uint8_t *>(dstPrefix), sizeof(PrefixTlv) + BitVectorBytes(aPrefix.GetPrefixLength()));
  1130          dstPrefix->Init(aPrefix.GetDomainId(), aPrefix.GetPrefixLength(), aPrefix.GetPrefix());
  1131      }
  1132
  1133      if (dstContext == NULL)
  1134      {
  1135          dstContext = static_cast<ContextTlv *>(dstPrefix->GetNext());
  1136          Insert(reinterpret_cast<uint8_t *>(dstContext), sizeof(ContextTlv));
  1137          dstPrefix->SetLength(dstPrefix->GetLength() + sizeof(ContextTlv));
  1138          dstContext->Init();
  1139          dstContext->SetCompress();
  1140          dstContext->SetContextId(static_cast<uint8_t>(contextId));
  1141          dstContext->SetContextLength(aPrefix.GetPrefixLength());
  1142      }
  1143
  1144      dstContext->SetCompress();
  1145      StopContextReuseTimer(dstContext->GetContextId());
  1146
  1147      if (dstBorderRouter == NULL)
  1148      {
  1149          dstBorderRouter = static_cast<BorderRouterTlv *>(dstPrefix->GetNext());
  1150          Insert(reinterpret_cast<uint8_t *>(dstBorderRouter), sizeof(BorderRouterTlv));
  1151          dstPrefix->SetLength(dstPrefix->GetLength() + sizeof(BorderRouterTlv));
  1152          dstBorderRouter->Init();
  1153      }
  1154
  1155      Insert(reinterpret_cast<uint8_t *>(dstBorderRouter->GetNext()), sizeof(BorderRouterEntry));
  1156      dstBorderRouter->SetLength(dstBorderRouter->GetLength() + sizeof(BorderRouterEntry));
  1157      dstPrefix->SetLength(dstPrefix->GetLength() + sizeof(BorderRouterEntry));
  1158      memcpy(dstBorderRouter->GetEntry(dstBorderRouter->GetNumEntries() - 1), aBorderRouter.GetEntry(0),
  1159             sizeof(BorderRouterEntry));
  1160
  1161      if (aBorderRouter.IsStable())
  1162      {
  1163          dstPrefix->SetStable();
  1164          dstContext->SetStable();
  1165          dstBorderRouter->SetStable();
  1166      }
  1167
  1168  exit:
  1169      return error;
  1170  }
